/**
 * @name Trace data flow to expandvars
 * @description Trace where the argument to expandvars comes from
 * @kind path-problem
 * @problem.severity warning
 * @id py/trace-expandvars
 * @tags security
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module ExpandVarsConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Consider all parameters of the function containing the call as sources initially
    // to see where the data enters the function scope.
    exists(Function f |
        f = source.getScope() and
        source instanceof DataFlow::ParameterNode
    )
    or
    // Also consider file reads or environment variables
    source = API::moduleImport("os").getMember("environ").getAValueReachableFromSource()
    or
    source = API::moduleImport("os").getMember("getenv").getACall()
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("expandvars").getMember("expandvars").getACall() or
      call = API::moduleImport("os").getMember("path").getMember("expandvars").getACall() |
      sink = call.getArg(0)
    )
  }
}

module ExpandVarsFlow = TaintTracking::Global<ExpandVarsConfig>;
import ExpandVarsFlow::PathGraph

from ExpandVarsFlow::PathNode source, ExpandVarsFlow::PathNode sink
where ExpandVarsFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "expandvars argument comes from $@.", source.getNode(), "source"

/**
 * @name Trace expandvars usage
 * @description Trace the result of expandvars to potential sinks
 * @kind path-problem
 * @problem.severity warning
 * @id py/trace-expandvars-usage
 * @tags security
 *       external/cwe/cwe-078
 *       external/cwe/cwe-073
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module ExpandVarsUsageConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source = API::moduleImport("expandvars").getMember("expandvars").getACall()
  }

  predicate isSink(DataFlow::Node sink) {
    // Command execution
    sink = API::moduleImport("subprocess").getMember(["call", "check_call", "check_output", "run", "Popen"]).getACall().getArg(_)
    or
    sink = API::moduleImport("os").getMember(["system", "popen", "spawnl", "spawnle", "spawnlp", "spawnlpe", "spawnv", "spawnve", "spawnvp", "spawnvpe"]).getACall().getArg(_)
    or
    // File access (path)
    sink = API::moduleImport("builtins").getMember("open").getACall().getArg(0)
    or
    // Path manipulation that might lead to file access
    sink = API::moduleImport("shutil").getMember(["copy", "copy2", "move"]).getACall().getArg(_)
  }
}

module ExpandVarsUsageFlow = TaintTracking::Global<ExpandVarsUsageConfig>;
import ExpandVarsUsageFlow::PathGraph

from ExpandVarsUsageFlow::PathNode source, ExpandVarsUsageFlow::PathNode sink
where ExpandVarsUsageFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Result of expandvars flows to sink."
